"use client"

import type { Implementation, Transport } from "@modelcontextprotocol/client"
import { App, type McpUiAppCapabilities, type McpUiDisplayMode, type McpUiHostCapabilities, type McpUiHostContext } from "@modelcontextprotocol/ext-apps"
import { createContext, useContext, useEffect, useState, type ReactNode } from "react"

import { applyHostContext } from "@/registry/mcpblocks/lib/host"
import { ToolNotificationsContext, type ToolNotifications } from "@/registry/mcpblocks/hooks/use-tool-result"

type HostConnection = {
  app: App | null
  context?: McpUiHostContext
  capabilities?: McpUiHostCapabilities
  platform?: McpUiHostContext["platform"]
  error: Error | null
  requestDisplayMode: (mode: McpUiDisplayMode) => Promise<McpUiDisplayMode | undefined>
}

type HostOptions = {
  appInfo: Implementation
  capabilities?: McpUiAppCapabilities
  autoResize?: boolean
  /** Apply host styles inside an embedded preview. Defaults to the document. */
  styleTarget?: HTMLElement
  /** Create a fresh transport for a connection. Defaults to the host iframe. */
  createTransport?: () => Transport
}

const HostContext = createContext<HostConnection | null>(null)
const disconnected: HostConnection = {
  app: null,
  error: null,
  requestDisplayMode: async () => undefined,
}

/** Mount one provider for a view. Connection options are read on mount. */
export function McpHostProvider({ children, ...options }: HostOptions & { children: ReactNode }) {
  const [configuration] = useState(options)
  const [connection, setConnection] = useState(disconnected)
  const [notifications, setNotifications] = useState<ToolNotifications>({})

  useEffect(() => {
    const app = new App(configuration.appInfo, configuration.capabilities, { autoResize: configuration.autoResize ?? true })
    const abort = new AbortController()
    let connected = false
    let context: McpUiHostContext | undefined
    let modeRevision = 0

    function applyContext(update: McpUiHostContext | undefined) {
      if (abort.signal.aborted) return
      context = { ...context, ...update }
      applyHostContext(context, configuration.styleTarget)
      if (connected) {
        setConnection({
          app,
          context,
          capabilities: app.getHostCapabilities(),
          platform: context.platform,
          error: null,
          requestDisplayMode,
        })
      }
    }

    async function requestDisplayMode(mode: McpUiDisplayMode) {
      if (!connected || abort.signal.aborted) return undefined
      if (context?.availableDisplayModes && !context.availableDisplayModes.includes(mode)) return context.displayMode
      const revision = ++modeRevision
      const actual = await app.requestDisplayMode({ mode })
      if (revision === modeRevision) applyContext({ displayMode: actual.mode })
      return actual.mode
    }

    app.addEventListener("hostcontextchanged", (update) => {
      if (update.displayMode) modeRevision++
      applyContext(update)
    })
    app.addEventListener("toolinputpartial", (partialInput) => setNotifications({ partialInput }))
    app.addEventListener("toolinput", (input) => setNotifications({ input }))
    app.addEventListener("toolresult", (result) => setNotifications((previous) => ({ ...previous, result, cancelled: undefined })))
    app.addEventListener("toolcancelled", (cancelled) => setNotifications((previous) => ({ ...previous, cancelled })))
    app.onclose = () => {
      if (abort.signal.aborted || !connected) return
      connected = false
      setConnection({ ...disconnected, error: new Error("The MCP host connection closed.") })
    }

    // Let Strict Mode finish its setup/cleanup cycle before opening a transport.
    void Promise.resolve().then(async () => {
      if (abort.signal.aborted) return
      await app.connect(configuration.createTransport?.(), { signal: abort.signal })
      if (abort.signal.aborted) return
      connected = true
      applyContext(app.getHostContext())
    }).catch((error: unknown) => {
      if (abort.signal.aborted) return
      setConnection({ ...disconnected, error: error instanceof Error ? error : new Error(String(error)) })
    })

    return () => {
      abort.abort()
      connected = false
      void app.close().catch(() => {})
    }
  }, [configuration])

  return (
    <HostContext.Provider value={connection}>
      <ToolNotificationsContext.Provider value={notifications}>{children}</ToolNotificationsContext.Provider>
    </HostContext.Provider>
  )
}

export function useHost(): HostConnection {
  const connection = useContext(HostContext)
  if (!connection) throw new Error("useHost must be used within McpHostProvider.")
  return connection
}

"use client"

import type { AppEventMap } from "@modelcontextprotocol/ext-apps"
import { createContext, useContext } from "react"

export type ToolNotifications = {
  input?: AppEventMap["toolinput"]
  partialInput?: AppEventMap["toolinputpartial"]
  result?: AppEventMap["toolresult"]
  cancelled?: AppEventMap["toolcancelled"]
}

export const ToolNotificationsContext = createContext<ToolNotifications | null>(null)

/** Latest partial input, complete input, result, and cancellation from the host. */
export function useToolResult() {
  const notifications = useContext(ToolNotificationsContext)
  if (!notifications) throw new Error("useToolResult must be used within McpHostProvider.")
  return notifications
}

"use client"

import { SdkError, SdkErrorCode, type CallToolResult } from "@modelcontextprotocol/client"
import { useCallback } from "react"

import { useHost } from "@/registry/mcpblocks/hooks/use-host"

export type ToolCallOutcome =
  | { kind: "result"; result: CallToolResult }
  | { kind: "error"; error: Error; result?: CallToolResult }
  | { kind: "timeout"; error: Error }
  | { kind: "unavailable" }

/** Call a server tool through the host and distinguish timeouts from explicit failures. */
export function useToolCall(name: string) {
  const { app, capabilities } = useHost()
  const available = !!app && !!capabilities?.serverTools

  const call = useCallback(async (
    args: Record<string, unknown> = {},
    { timeoutMs }: { timeoutMs?: number } = {},
  ): Promise<ToolCallOutcome> => {
    if (!app || !available) return { kind: "unavailable" }

    try {
      const result = await app.callServerTool({ name, arguments: args }, { timeout: timeoutMs })
      if (result.isError) {
        const message = result.content?.find((block) => block.type === "text")?.text
        return { kind: "error", error: new Error(message ?? "The tool returned an error."), result }
      }
      return { kind: "result", result }
    } catch (cause) {
      const error = cause instanceof Error ? cause : new Error(String(cause))
      if (cause instanceof SdkError && cause.code === SdkErrorCode.RequestTimeout) return { kind: "timeout", error }
      return { kind: "error", error }
    }
  }, [app, available, name])

  return { call, available }
}

"use client"

import { useEffect, useRef, useState } from "react"

import { useHost } from "@/registry/mcpblocks/hooks/use-host"
import { tellModel } from "@/registry/mcpblocks/lib/host"

export type PreparedWrite<TPreview> = { preview: TPreview; idempotencyKey: string }

export type PrepareOutcome<TPreview> =
  | { kind: "preview"; preview: TPreview }
  | { kind: "blocked"; reason: string }

export type WriteOutcome<TResult> =
  | { kind: "saved"; result: TResult; summary: string }
  | { kind: "refused"; reason: string }
  | { kind: "unknown"; reason?: string }

export type PreparedWriteState<TPreview, TResult> =
  | { status: "idle" | "preparing" }
  | ({ status: "preview" | "confirming" | "checking" } & PreparedWrite<TPreview>)
  | ({ status: "unknown"; reason?: string } & PreparedWrite<TPreview>)
  | { status: "blocked" | "refused"; reason: string }
  | { status: "saved"; result: TResult }

type PreparedWriteOptions<TInput, TPreview, TResult> = {
  prepare: (input: TInput, idempotencyKey: string) => Promise<PrepareOutcome<TPreview>>
  execute: (write: PreparedWrite<TPreview>) => Promise<WriteOutcome<TResult>>
  reconcile: (write: PreparedWrite<TPreview>) => Promise<WriteOutcome<TResult>>
  /** A proposal already prepared by the tool that opened this view. Read on mount. */
  initialPreview?: TPreview
  fallbackToMessage?: boolean
}

function canCloseWrite(status: PreparedWriteState<unknown, unknown>["status"]) {
  return status !== "preparing" && status !== "confirming" && status !== "unknown" && status !== "checking"
}

/** Prepare one proposal, confirm once, and reconcile uncertain outcomes using the original key. */
export function usePreparedWrite<TInput, TPreview, TResult>(options: PreparedWriteOptions<TInput, TPreview, TResult>) {
  const { app } = useHost()
  const [state, setState] = useState<PreparedWriteState<TPreview, TResult>>(() =>
    options.initialPreview === undefined
      ? { status: "idle" }
      : { status: "preview", preview: options.initialPreview, idempotencyKey: crypto.randomUUID() },
  )
  const current = useRef(state)
  const mounted = useRef(true)

  useEffect(() => {
    mounted.current = true
    return () => { mounted.current = false }
  }, [])

  function transition(next: PreparedWriteState<TPreview, TResult>) {
    if (!mounted.current) return
    current.current = next
    setState(next)
  }

  async function prepare(input: TInput) {
    if (!mounted.current || !canCloseWrite(current.current.status)) return
    const idempotencyKey = crypto.randomUUID()
    transition({ status: "preparing" })
    try {
      const outcome = await options.prepare(input, idempotencyKey)
      transition(outcome.kind === "preview"
        ? { status: "preview", preview: outcome.preview, idempotencyKey }
        : { status: "blocked", reason: outcome.reason })
    } catch (cause) {
      transition({ status: "blocked", reason: cause instanceof Error ? cause.message : "The change could not be prepared." })
    }
  }

  async function settle(
    write: PreparedWrite<TPreview>,
    status: "confirming" | "checking",
    operation: PreparedWriteOptions<TInput, TPreview, TResult>["execute"],
  ) {
    const { preview, idempotencyKey } = write
    const proposal = { preview, idempotencyKey }
    transition({ ...proposal, status })
    let outcome: WriteOutcome<TResult>
    try {
      outcome = await operation(proposal)
    } catch {
      outcome = { kind: "unknown" }
    }
    if (!mounted.current) return

    switch (outcome.kind) {
      case "saved":
        transition({ status: "saved", result: outcome.result })
        if (app) void tellModel(app, outcome.summary, { fallbackToMessage: options.fallbackToMessage })
        break
      case "refused":
        transition({ status: "refused", reason: outcome.reason })
        break
      case "unknown":
        transition({ ...proposal, status: "unknown", reason: outcome.reason })
        break
    }
  }

  async function confirm() {
    const write = current.current
    if (mounted.current && write.status === "preview") await settle(write, "confirming", options.execute)
  }

  async function checkAgain() {
    const write = current.current
    if (mounted.current && write.status === "unknown") await settle(write, "checking", options.reconcile)
  }

  function reset() {
    if (canCloseWrite(current.current.status)) transition({ status: "idle" })
  }

  return { state, canClose: canCloseWrite(state.status), prepare, confirm, checkAgain, reset }
}
